// อ่าน event จาก LINE + หา/ตรวจ "ลายเซ็น" (X-Line-Signature)
const inp = $input.first();
const j = (inp && inp.json) || {};
const headers = j.headers || {};
const sig = headers['x-line-signature'] || headers['X-Line-Signature'] || '';

// หา raw body (ต้องเปิด option "Raw Body" ในโหนด LINE Webhook ถึงจะตรวจ HMAC ได้)
let raw = null;
if (typeof j.rawBody === 'string') raw = j.rawBody;
else if (typeof j.body === 'string') raw = j.body;
else if (inp && inp.binary && inp.binary.data) {
  try { const d = inp.binary.data; raw = Buffer.from(d.data || d, 'base64').toString('utf8'); } catch (e) {}
}

// events: จาก raw (ถ้ามี) มิฉะนั้นจาก body ที่ n8n parse ให้แล้ว
let payload = {};
if (raw) { try { payload = JSON.parse(raw); } catch (e) { payload = (j.body && typeof j.body === 'object') ? j.body : {}; } }
else payload = (j.body && typeof j.body === 'object') ? j.body : {};
const events = Array.isArray(payload.events) ? payload.events : [];

// ตรวจลายเซ็น HMAC-SHA256(channel secret, raw) เทียบ header  (null = ยังตรวจไม่ได้)
let secret = ''; try { secret = ($env && $env.LINE_CHANNEL_SECRET) || ''; } catch (e) { secret = ''; }
let sigValid = null;
try {
  if (secret && raw) {
    const crypto = require('crypto');
    const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('base64');
    sigValid = (expected === sig);
  }
} catch (e) { sigValid = null; }

// ออก 1 item ต่อ 1 ข้อความ (event ที่เป็น message) — LINE verify (events=[]) จะได้ [] ไม่ตอบกลับ
const out = [];
for (const ev of events) {
  if (!ev || ev.type !== 'message' || !ev.message) continue;
  const s = ev.source || {};
  out.push({ json: {
    sourceType: s.type || '', userId: s.userId || '', groupId: s.groupId || '', roomId: s.roomId || '',
    replyToken: ev.replyToken || '', msgType: ev.message.type || '', text: ev.message.text || '',
    xLineSignature: sig, sigValid: sigValid, ts: ev.timestamp || null
  }});
}
return out;

// ============================================================
// ตัวแยกคำสั่ง LINE → แก้ข้อมูลการผลิต (เฟส เคส 1–2: เลื่อนส่ง / แก้จำนวน)
// pure functions (unit-testable) — n8n Code node เรียกใช้ผ่าน plumbing
// ============================================================

// ---------- helpers ----------
const nows = s => String(s == null ? '' : s).replace(/\s+/g, '');
const num  = v => Number(String(v == null ? '' : v).replace(/,/g, '')) || 0;
const fmt  = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const normMachine = m => { m = String(m == null ? '' : m).trim().toUpperCase().replace(/\s+/g, ''); return m === 'TE1' ? 'TE' : m; };

// อ่านค่าจากแถวชีตแบบทนช่องว่าง/ขึ้นบรรทัดในชื่อคอลัมน์ (เช่น "จำนวนที่ต้องผลิตเพิ่ม (ใบ)" / "วัน Delivery")
function pgetKey(row, target){ const t = nows(target); for (const k in row){ if (nows(k).startsWith(t)) return k; } return null; }
function pget(row, target){ const k = pgetKey(row, target); return k == null ? undefined : row[k]; }

// normalize วันที่ -> d/m/yyyy (รับ dd/mm/yyyy, yyyy-mm-dd, พ.ศ.)
function toDMY(s){
  const t = String(s == null ? '' : s).trim();
  let m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/); if (m){ let Y=+m[3]; if(Y>2400)Y-=543; if(Y<100)Y+=2000; return `${+m[1]}/${+m[2]}/${Y}`; }
  m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m){ let Y=+m[1]; if(Y>2400)Y-=543; return `${+m[3]}/${+m[2]}/${Y}`; }
  return null;
}

// ---------- parse ----------
const KW = ['เลื่อนส่ง', 'แก้จำนวน', 'ปิดงาน', 'ย้ายเครื่อง', 'ย้ายงาน', 'เปิดเครื่อง', 'ปิดเครื่อง'];
const LABELS = { 'เครื่อง':'machine', 'สินค้า':'product', 'ส่งใหม่':'newDelivery', 'จำนวนใหม่':'newQty',
                 'เริ่ม':'start', 'เครื่องเสีย':'brokenMachine', 'ย้ายไป':'toMachine' };
function normLabel(s){ const t = String(s || '').trim(); if (t.toLowerCase() === 'delivery') return 'delivery'; return LABELS[t] || null; }

function parseCommand(text){
  const raw = String(text == null ? '' : text).trim();
  if (/^ยืนยัน\b/.test(raw) || raw === 'ยืนยัน') return { intent:'confirm' };
  if (/^ยกเลิก\b/.test(raw) || raw === 'ยกเลิก') return { intent:'cancel' };
  if (/^(help|วิธีใช้|คำสั่ง|เมนู)$/i.test(raw)) return { intent:'help' };
  const lines = raw.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
  let kw = '', kwval = '';
  for (const ln of lines){
    if (KW.includes(ln)){ kw = ln; break; }
    const m = ln.match(/^(เลื่อนส่ง|แก้จำนวน|ปิดงาน|ปิดเครื่อง|ย้ายเครื่อง|ย้ายงาน|เปิดเครื่อง)\s*[:：]?\s*(.*)$/);
    if (m){ kw = m[1]; kwval = (m[2] || '').trim(); break; }
  }
  if (!kw) return { intent:'chat' };
  const fields = {};
  for (const ln of lines){
    if (KW.includes(ln) || ln.indexOf(kw) === 0) continue;   // ข้ามบรรทัด keyword (bare หรือ keyword: value)
    const m = ln.match(/^([^:：]+)[:：]\s*(.*)$/); if (!m) continue;
    const key = normLabel(m[1]); if (key) fields[key] = m[2].trim();
  }
  const cmdMap = { 'เลื่อนส่ง':'delivery', 'แก้จำนวน':'qty', 'ปิดงาน':'close', 'ย้ายเครื่อง':'move', 'ย้ายงาน':'movejob', 'เปิดเครื่อง':'open', 'ปิดเครื่อง':'shut' };
  return { intent:'cmd', cmd: cmdMap[kw] || 'move', fields, kwval };
}

// ---------- match order ใน Planning ----------
function matchOrder(planningRows, fields){
  const tMachine = normMachine(fields.machine), tProd = nows(fields.product);
  if (!tMachine || !tProd) return { status:'badinput' };
  let cand = (planningRows || []).filter(r => {
    const rm = normMachine(pget(r, 'เครื่องจักร')), rp = nows(pget(r, 'ชื่อสินค้า'));
    return rm === tMachine && rp && (rp.includes(tProd) || tProd.includes(rp));
  });
  // ให้ความสำคัญงานที่ยังไม่จบ (คงเหลือ > 0)
  const active = cand.filter(r => (num(pget(r, 'จำนวนที่ต้องผลิตเพิ่ม')) - num(pget(r, 'จำนวนที่ผลิตแล้ว'))) > 0);
  if (active.length) cand = active;
  // แยกความกำกวมด้วย Delivery/เริ่ม
  if (cand.length > 1 && (fields.delivery || fields.start)){
    cand = cand.filter(r => {
      if (fields.delivery) return nows(pget(r, 'วันDelivery')).includes(nows(fields.delivery));
      if (fields.start)    return nows(pget(r, 'วันที่ผลิต')).includes(nows(fields.start));
      return true;
    });
  }
  if (cand.length === 0) return { status:'none' };
  if (cand.length > 1)  return { status:'many', matches:cand };
  return { status:'ok', row:cand[0] };
}

// ---------- build confirm (สรุปก่อนยืนยัน) ----------
function buildConfirm(cmd, row, fields){
  const machine = String(pget(row, 'เครื่องจักร') || '').trim();
  const prod = String(pget(row, 'ชื่อสินค้า') || '').trim();
  const rn = pget(row, 'row_number');
  if (cmd === 'delivery'){
    const nd = toDMY(fields.newDelivery);
    if (!nd) return { ok:false, error:'รูปแบบวันที่ไม่ถูก ใช้ วว/ดด/ปปปป เช่น 15/07/2026' };
    const old = String(pget(row, 'วันDelivery') || '-').trim();
    return { ok:true, field:pgetKey(row, 'วันDelivery'), value:nd, row_number:rn,
             summary:`เลื่อนส่ง ${prod} (${machine}) → ${nd}`,
             reply:`ยืนยันการแก้ไข?\n• งาน: ${prod} (${machine})\n• เลื่อนวันส่ง: ${old} → ${nd}\nพิมพ์ "ยืนยัน" ใน 5 นาที (หรือ "ยกเลิก")` };
  }
  if (cmd === 'qty'){
    const nq = num(fields.newQty);
    if (!nq || nq <= 0) return { ok:false, error:'จำนวนใหม่ไม่ถูกต้อง ใส่ตัวเลข > 0 (หน่วยใบ)' };
    const oldQ = num(pget(row, 'จำนวนที่ต้องผลิตเพิ่ม'));
    const prod0 = num(pget(row, 'จำนวนที่ผลิตแล้ว'));
    let note = '';
    if (prod0 > 0) note = nq <= prod0 ? `\n• ผลิตแล้ว ${fmt(prod0)} → เกินเป้าใหม่ งานนี้จะถูกปิด (คงเหลือ 0)` : `\n• ผลิตแล้ว ${fmt(prod0)} · คงเหลือใหม่ ${fmt(nq - prod0)}`;
    return { ok:true, field:pgetKey(row, 'จำนวนที่ต้องผลิตเพิ่ม'), value:nq, row_number:rn,
             summary:`แก้จำนวน ${prod} (${machine}) → ${fmt(nq)} ใบ`,
             reply:`ยืนยันการแก้ไข?\n• งาน: ${prod} (${machine})\n• แก้ยอดผลิต: ${fmt(oldQ)} → ${fmt(nq)} ใบ${note}\nพิมพ์ "ยืนยัน" ใน 5 นาที (หรือ "ยกเลิก")` };
  }
  if (cmd === 'close'){
    const prod0 = num(pget(row, 'จำนวนที่ผลิตแล้ว'));
    return { ok:true, row_number:rn, produced:prod0,
             summary:`ปิดงาน ${prod} (${machine}) · ผลิตแล้ว ${fmt(prod0)} ใบ`,
             reply:`ยืนยันปิดงาน?\n• งาน: ${prod} (${machine})\n• ปิดที่ยอดผลิตแล้ว ${fmt(prod0)} ใบ (เหลือ 0)\n• งานถัดไปบนเครื่องนี้จะเลื่อนขึ้นมาแทน\nพิมพ์ "ยืนยัน" ใน 5 นาที (หรือ "ยกเลิก")` };
  }
  return { ok:false, error:'ยังไม่รองรับคำสั่งนี้' };
}

// ---------- apply (ตอน "ยืนยัน") ----------
function applyConfirm(pending){
  const update = { row_number: pending.row_number };
  update[pending.field] = pending.value;
  return { update, reply:`อัปเดตแล้ว ✓\n${pending.summary}\n(จะจัดตารางใหม่ในรอบถัดไป)` };
}


