  const s = pget(r, 'สถานะ'); if (s === undefined || s === null) continue;
  const m = normMachine(pget(r, 'เครื่องจักร')); if (!m) continue;
  statusRowOf[m] = r['row_number'];
  if (!/เสีย|พัง|ปิด|หยุด|ซ่อม/.test(String(s))) usable.push(m);
}

if (cmd.intent === 'help') {
  reply = 'คำสั่ง (พิมพ์ทีละบรรทัด):\n① เลื่อนส่ง / เครื่อง / สินค้า / ส่งใหม่\n② แก้จำนวน / เครื่อง / สินค้า / จำนวนใหม่\n③ ปิดงาน / เครื่อง / สินค้า\n④ ย้ายเครื่อง / เครื่องเสีย / (ย้ายไป)\n⑤ ย้ายงาน / เครื่อง / เริ่ม / ย้ายไป\n⑥ เปิดเครื่อง: <เครื่อง>  ·  ปิดเครื่อง: <เครื่อง>\nยืนยัน=ยืนยัน · ยกเลิก=ยกเลิก';
} else if (cmd.intent === 'cancel') {
  if (sd.pending[key]) { delete sd.pending[key]; reply = 'ยกเลิกแล้ว'; } else reply = 'ไม่มีรายการรอยืนยัน';
} else if (cmd.intent === 'confirm') {
  const pend = sd.pending[key];
  if (!pend) reply = 'ไม่มีรายการรอยืนยัน · ส่งคำสั่งก่อน';
  else if (Date.now() - pend.ts > TTL) { delete sd.pending[key]; reply = 'รายการหมดอายุ (เกิน 5 นาที) · ส่งคำสั่งใหม่'; }
  else {
    let res = { raykRows: [], planRows: [] };
    if (pend.type === 'delivery') res = { raykRows: [], planRows: [{ row_number: pend.planRowNumber, 'วัน Delivery': pend.value }] };
    else if (pend.type === 'qty')     res = applyQty(parseJobs(raykar), pend.machine, pend.prod, pend.newQty, rateFor, pend.planRowNumber, now);
    else if (pend.type === 'close')   res = applyClose(parseJobs(raykar), pend.machine, pend.prod, pend.produced, rateFor, pend.planRowNumber, now);
    else if (pend.type === 'movejob') res = applyMoveJob(parseJobs(raykar), pend.machine, pend.start, pend.toMachine, rateFor, now, planRowOf);
    else if (pend.type === 'move') {
      res = applyMove(parseJobs(raykar), pend.brokenM, pend.targetM, rateFor, now, planRowOf, usable);
      if (!res.error) { const brk = normMachine(pend.brokenM); if (statusRowOf[brk] != null) statusRows = [{ row_number: statusRowOf[brk], 'สถานะ': 'เสีย', 'อัปเดตเมื่อ': todayStr }]; }
    }
    if (res.error) reply = res.error;
    else { raykRows = res.raykRows || []; planRows = res.planRows || []; doWrite = (raykRows.length + planRows.length + statusRows.length) > 0;
           reply = 'อัปเดตแล้ว ✓\n' + pend.summary + '\nวางแผนใหม่ (เวลา/คน) + เขียนกลับแล้ว'; }
    delete sd.pending[key];
  }
} else if (cmd.intent === 'cmd') {
  if (cmd.cmd === 'open' || cmd.cmd === 'shut') {
    const mm = normMachine(cmd.fields.machine || cmd.kwval || cmd.fields.brokenMachine || '');
    if (!mm) reply = 'ระบุเครื่อง เช่น "เปิดเครื่อง: PF8/5"';
    else if (statusRowOf[mm] == null) reply = 'ไม่พบ ' + (cmd.fields.machine || cmd.kwval) + ' ในชีต machine_status (ยังไม่ได้สร้าง/เพิ่มแถว หรือยังไม่เลือกแท็บในโหนด)';
    else { statusRows = [{ row_number: statusRowOf[mm], 'สถานะ': (cmd.cmd === 'open' ? 'ใช้งานได้' : 'เสีย'), 'อัปเดตเมื่อ': todayStr }];
           doWrite = true; reply = (cmd.cmd === 'open' ? '✅ เปิดเครื่อง ' : '⛔ ปิดเครื่อง ') + mm + ' → ' + (cmd.cmd === 'open' ? 'ใช้งานได้' : 'เสีย'); }
  } else if (cmd.cmd === 'move') {
    const bm = cmd.fields.brokenMachine || cmd.kwval, tm = cmd.fields.toMachine || '';
    if (!bm) reply = 'ระบุ เครื่องเสีย: <เครื่อง>';
    else {
      const pm = planMoveTargets(parseJobs(raykar), bm, tm, rateFor, now, usable);
      if (pm.error) reply = pm.error;
      else { const tgs = [...pm.targets].join(', ');
        sd.pending[key] = { type: 'move', brokenM: bm, targetM: tm, summary: 'ย้ายงาน ' + bm + ' → ' + tgs + ' (' + pm.moving.length + ' งาน)', ts: Date.now() };
        reply = 'ยืนยันย้ายเครื่อง (เครื่องเสีย)?\n• ' + bm + ' → ' + tgs + (tm ? '' : ' (auto: เครื่องว่าง+ใช้งานได้)') + '\n• พัก ' + bm + ' (มาร์คเสียในชีต) · ย้าย ' + pm.moving.length + ' งาน · เริ่มทันทีถ้าเครื่องว่าง\nพิมพ์ "ยืนยัน" ใน 5 นาที'; }
    }
  } else if (cmd.cmd === 'movejob') {
    const m = cmd.fields.machine, st = cmd.fields.start, tg = cmd.fields.toMachine;
    if (!m || !st || !tg) reply = 'ใส่ให้ครบ:\nย้ายงาน\nเครื่อง: <เครื่อง>\nเริ่ม: วว/ดด/ปปปป\nย้ายไป: <เครื่อง>';
    else {
      const sY = toYMD(st);
      const job = sY ? parseJobs(raykar).filter(j => j.mkey === normMachine(m) && fmtYMD2(j.ps) === sY && j.pe > now).sort((a,b)=>a.ps-b.ps)[0] : null;
      if (!sY) reply = 'รูปแบบวันเริ่มไม่ถูก ใช้ วว/ดด/ปปปป';
      else if (!job) reply = 'ไม่พบงานบน ' + m + ' ที่เริ่มวันที่ ' + st;
      else { const pn = job.items[0] ? String(job.items[0].name).split('|')[0].trim() : '';
        sd.pending[key] = { type: 'movejob', machine: m, start: st, toMachine: tg, summary: 'ย้ายงาน ' + pn + ' (' + m + ' เริ่ม ' + st + ') → ' + tg, ts: Date.now() };
        reply = 'ยืนยันย้ายงาน?\n• ' + pn + ' บน ' + m + ' (เริ่ม ' + st + ')\n• → ' + tg + '\nพิมพ์ "ยืนยัน" ใน 5 นาที'; }
    }
  } else {
    const mo = matchOrder(planning, cmd.fields);
    if (mo.status === 'badinput') reply = 'ใส่ข้อมูลไม่ครบ ต้องมี เครื่อง: และ สินค้า:';
    else if (mo.status === 'none') reply = 'ไม่พบออเดอร์ ' + (cmd.fields.machine || '') + ' + ' + (cmd.fields.product || '') + ' ในแผน · เช็กชื่อ/เครื่องอีกที';
    else if (mo.status === 'many') {
      const lst = mo.matches.slice(0, 5).map(r => '- ' + String(pget(r, 'ชื่อสินค้า') || '').trim() + ' · ส่ง ' + String(pget(r, 'วันDelivery') || '-').trim()).join('\n');
      reply = 'เจอหลายรายการ ระบุให้ชัดโดยเติม Delivery: หรือ เริ่ม:\n' + lst;
    } else {
      const c = buildConfirm(cmd.cmd, mo.row, cmd.fields);
      if (!c.ok) reply = c.error;
      else {
        const pend = { type: cmd.cmd, ts: Date.now(), summary: c.summary, planRowNumber: c.row_number };
        const mach = String(pget(mo.row, 'เครื่องจักร') || '').trim(), pcore = core(pget(mo.row, 'ชื่อสินค้า'));
        if (cmd.cmd === 'delivery') pend.value = c.value;
        else if (cmd.cmd === 'qty')   { pend.machine = mach; pend.prod = pcore; pend.newQty = c.value; }
        else if (cmd.cmd === 'close') { pend.machine = mach; pend.prod = pcore; pend.produced = c.produced; }
        sd.pending[key] = pend; reply = c.reply;
      }
    }
  }
} else reply = '';

if (!reply) return [];
return [{ json: { to, replyText: reply, doWrite, raykRows, planRows, statusRows } }];
